<div class="tt-grid"><div class="card tt-card"><form id="ttForm" method="POST" action="{{route('termination-types-store')}}" novalidate>@csrf<span id="ttMethod"></span><div class="card-header"><h3 id="ttTitle">Add New Termination Type</h3></div><div class="card-body"><div class="mb-5"><label class="form-label required">Type Name</label><input class="form-control" name="name" placeholder="e.g. Retirement, Misconduct"></div><div class="mb-5"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description" placeholder="Brief description"></textarea></div><div class="mb-5"><label class="form-label required">Status</label><select class="form-select" name="status"><option value="1">Active</option><option value="0">Inactive</option></select></div><button class="btn btn-success" id="ttSave">Add Termination Type</button><button type="button" class="btn btn-light" id="ttCancel" style="display:none" onclick="resetTT()">Cancel</button></div></form></div><div><div class="card tt-card mb-5"><form class="card-body d-flex gap-3"><input class="form-control" name="search" value="{{request('search')}}" placeholder="Search termination types..."><button class="btn btn-success">Search</button></form></div><div class="card tt-card overflow-hidden"><div class="tt-row fw-bold bg-light"><span>Name</span><span>Status</span><span class="text-center">Actions</span></div>@forelse($types as $t)<div class="tt-row"><div><strong>{{$t->name}}</strong><div class="text-muted">{{$t->description?:'—'}}</div></div><span><span class="badge badge-light-{{$t->status?'success':'danger'}}">{{$t->status?'Active':'Inactive'}}</span></span><div class="tt-actions d-flex justify-content-center gap-3"><button title="Edit" data-item="{{base64_encode(json_encode($t))}}" onclick="editTT(this.dataset.item)"><svg viewBox="0 0 24 24"><path d="M12 20H5a1 1 0 0 1-1-1v-7"/><path d="m16.5 3.5 4 4L11 17l-5 1 1-5Z"/></svg></button><form method="POST" action="{{route('termination-types-togg