<script>const ttStore=@json(route('termination-types-store')),ttUpdate=@json(route('termination-types-update','__ID__'));function editTT(x){let d=JSON.parse(atob(x)),f=ttForm;f.action=ttUpdate.replace('__ID__',d.id);ttMethod.innerHTML='<input type="hidden" name="_method" value="PUT">';f.elements.name.value=d.name;f.elements.description.value=d.description||'';f.elements.status.value=d.status?1:0;ttTitle.textContent='Edit Termination Type';ttSave.textContent='Update Termination Type';ttCancel.style.display='inline-block';scrollTo({top:0,behavior:'smooth'})}function resetTT(){ttForm.reset();ttForm.action=ttStore;ttMethod.innerHTML='';ttTitle.textContent='Add New Termination Type';ttSave.textContent='Add Termination Type';ttCancel.style.display='none'}document.addEventListener('DOMContentLoaded',()=>{ttForm.onsubmit=e=>{ttForm.querySelectorAll('.tt-error').forEach(x=>x.remove());if(!ttForm.elements.name.value.trim()){e.preventDefault();ttForm.elements.name.insertAdjacentHTML('afterend','<div class="tt-error">Type Name is required</div>')}};document.querySelectorAll('.tt-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete termination type?',text:'This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})})})</script>
